var a=`0145-khashlama`;var i=`world-0145`;var n=`AM`;var o=`western-asia`;var s=4;var l=148;var r={en:`Khashlama`,ua:`Хашлама`};var m={en:`A classic dish from Armenia, featuring lamb shoulder, yellow onion, bay leaf, potato. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Вірменія. Основні складники: лопатка ягняти, жовта цибуля, лавровий лист, картопля. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 110 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 110 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:110,i:[[`lamb-shoulder`,750,`g`],[`water`,1200,`ml`],[`yellow-onion`,240,`g`],[`bay-leaf`,2,`leaf`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 35 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 35 хвилин до м’якості та готовності.`,t:[`simmering`],m:35,i:[[`potato`,420,`g`],[`tomato`,330,`g`],[`red-bell-pepper`,260,`g`],[`carrot`,180,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,25,`g`],[`table-salt`,null,`to_taste`]]}];var d={slug:a,id:i,country:`AM`,region:o,servings:4,minutes:148,title:r,text:m,steps:g};export{n as country,d as default,i as id,l as minutes,o as region,s as servings,a as slug,g as steps,m as text,r as title};